with release_notes (ordinal, title, summary) as (
  values
    (1, 'October update - YouTube watching presence',
      'Added an opt-in Chromium extension for Chrome, Edge, and Brave that shares current YouTube watch-page and Shorts playback, including paused videos. Sharing starts off, uses a revocable device token stored locally rather than in Chrome Sync, and needs no YouTube API key or Google OAuth grant. Reports expire within 90 seconds without updates; phone/TV apps and incognito windows are excluded. Turn sharing off before private viewing. Setup and privacy instructions are in the GitHub Wiki.'),
    (2, 'October update - Shared media player and continuous sessions',
      'YouTube and Spotify now share the existing player area with previous/next arrows. Playing media takes priority over paused media; otherwise the earlier continuous listening/watching session appears first. Song/video changes and seeking do not reset a session, while pauses preserve it as observations continue. Session starts reflect the first server observation, not playback position; observation gaps over 90 seconds restart timing. Added persistent session tracking, paused clocks, local expiry, independent service-failure handling, and desktop/mobile accessibility checks.'),
    (3, 'October update - Creator photos, lookup, and Twitch',
      'Expanded CREATOR.FEED with automatic YouTube channel photos and authenticated channel lookup that fills canonical links and channel IDs. Twitch creators gained lookup, profile photos, live titles/categories, and the latest available archived broadcast when offline. Lookups preserve edits made while a request is running and ask before replacing a YouTube integration. Admin now displays the server explanation instead of a generic non-2xx error. Twitch credentials stay in Supabase; unavailable media never removes working channel links.'),
    (4, 'October update - Supabase message library and scheduled pools',
      'Moved editable status messages, activities, shutdown lines, fixed boot entries, desktop jokes, and monitor chatter into the Supabase-backed Admin Message library. Added search, pagination, enabled/disabled filters, rarity weights, previews, explicit row editors, and page-scoped bulk actions with unsaved-change protection. Custom date-ranged pools support additive/exclusive scheduling and a configured timezone. Cached or bundled messages remain available during outages; empty categories keep usable fallbacks. Refreshes preserve the selected calendar day across midnight.'),
    (5, 'October update - Inline messages, Mistype, and quote authors',
      'Added opt-in safe inline message styling and configurable Mistype corrections while keeping existing plain text literal. Status quotations support optional authors in a separate box: quote and author type concurrently, wait until both finish, then erase together. Unicode attribution is grapheme-safe, survives history/correction/cache/scheduled pools, and can be removed in Admin. Raw HTML, links, images, and media are not message markup. Export a fresh content backup after the catalog schema migrations; older exact-schema backups are rejected.'),
    (6, 'October update - Boot generator counts and message performance',
      'Admin now distinguishes editable fixed boot messages from the procedural generator: 29 actions x 37 subjects x 30 results provide 32,190 combinations, alongside fixed, phase, themed, and event lines. Admin and the endless-boot display share generator definitions so counts cannot drift. Added status-aware pagination/counts, shared fallback behavior, incremental refresh/cache scheduling, and calendar conversion that avoids unnecessary locale initialization. Browser snapshot checks now pause only message ticks during assertions, fixing a quote-author timing race without changing production animation.'),
    (7, 'October update - Expanded themes and Aero Glass variants',
      'Expanded the full-interface theme collection and experimental layouts, including E-Ink Reader, Blueprint, Spacecraft Console, Frutiger Eco, Holographic Foil, Newspaper, Workbench, Stickerbook, Night Train, and Museum Terminal. Aero Glass gained Windows 7, Vista, Graphite, Rose, and Frost alongside its unchanged Classic look. Added lazy-loaded styles, remembered variants, light/dark support where available, distinct atmospheres, accessible focus treatments, and an optional E-Ink refresh effect that starts off and respects motion/effects preferences.'),
    (8, 'October update - Theme families and native workspaces',
      'Replaced Online''s long theme dropdown with bounded, keyboard-friendly families, subthemes, and variants in View and Settings, preserving saved preferences and experimental labels. Experimental themes keep their native workspace when the main shell is minimized and expose a persistent Open workspace control. Added real-site app taskbars, tiles, browser tabs, terminal-style sessions, office/search panels, media collections, and BIOS-style navigation, plus mobile refinements, shareable URL restoration, regular-desktop fallback, and explicit asset-load retry. These are site parodies, not SSH, firmware, or audio players.'),
    (9, 'October update - Profile portrait and artist credit',
      'Added an optimized WebP profile portrait to the Online header with visible credit to Kay (@galacticcookie). The portrait sits beside the profile text and interactive bit avatar; narrow screens place the portrait and avatar above the text. Existing avatar reactions and Easter eggs remain available, while the high-priority portrait avoids transferring the full favicon asset for the page''s largest-contentful paint.'),
    (10, 'October update - 404 particles and responsive polish',
      'The not-found page now uses falling 404, 4, and 0 particles rather than generic Bits, with reduced-motion, decorative-effects, and forced-color preferences respected. Improved mobile profile, theme-picker, and workspace layouts so content and controls remain within the viewport. Added browser checks for particle behavior, responsive layout, retryable workspaces, and accessibility.'),
    (11, 'October update - Organized assets, Wiki, and deployment checks',
      'Reorganized browser assets into shared and page-owned folders without changing public page routes. Moved detailed setup and operations guidance from the README into focused GitHub Wiki pages, with a recent-changes overview and YouTube installation/token troubleshooting. Extension source and private tooling remain outside public builds. CI now installs Chromium for unpacked-extension checks and validates the shared media player. Documentation distinguishes validation, Supabase migration, site deployment, and later audit failures so a pushed commit is not mistaken for an applied database change.')
), last_position as (
  select coalesce(max(position), 0) as position from public.site_changelog
)
insert into public.site_changelog (position, entry_date, title, summary, enabled, updated_at)
select last_position.position + release_notes.ordinal, date '2026-10-26',
  release_notes.title, release_notes.summary, true, now()
from release_notes cross join last_position
order by release_notes.ordinal;
